# Feature: claude-simulator, Property 9: Auto-generated conversation title
# Validates: Requirements 3.5
"""
Property-based test verifying that _generate_title always returns a non-null,
non-empty string of at most 255 characters.

For any new conversation that receives its first user message, the conversation's
title field SHALL be non-null and non-empty after the message is processed.
"""

import json
from unittest.mock import MagicMock, patch

import pytest
from hypothesis import given, settings
from hypothesis import strategies as st

from app.api.chat import _generate_title

# Strategy: generate various user messages (non-empty)
user_message_strategy = st.text(min_size=1, max_size=500).filter(lambda s: s.strip())


class TestPropertyAutoGeneratedTitle:
    """**Validates: Requirements 3.5**"""

    @given(user_message=user_message_strategy)
    @settings(max_examples=100)
    @pytest.mark.asyncio
    async def test_generate_title_returns_non_null_non_empty_string(
        self, user_message: str
    ) -> None:
        """_generate_title SHALL return a non-null, non-empty string for any
        user message, even when Bedrock returns varied content."""
        mock_body = MagicMock()
        mock_body.read.return_value = json.dumps({
            "content": [{"type": "text", "text": "Chat about coding"}]
        }).encode()

        mock_response = {"body": mock_body}
        mock_client = MagicMock()
        mock_client.invoke_model.return_value = mock_response

        with patch("app.api.chat.boto3.client", return_value=mock_client):
            title = await _generate_title(user_message)

        assert title is not None
        assert isinstance(title, str)
        assert len(title) > 0
        assert title.strip() != ""

    @given(user_message=user_message_strategy)
    @settings(max_examples=100)
    @pytest.mark.asyncio
    async def test_generate_title_at_most_255_characters(
        self, user_message: str
    ) -> None:
        """_generate_title SHALL return a title of at most 255 characters,
        truncating if necessary."""
        # Simulate Bedrock returning a very long title
        long_title = "A" * 500
        mock_body = MagicMock()
        mock_body.read.return_value = json.dumps({
            "content": [{"type": "text", "text": long_title}]
        }).encode()

        mock_response = {"body": mock_body}
        mock_client = MagicMock()
        mock_client.invoke_model.return_value = mock_response

        with patch("app.api.chat.boto3.client", return_value=mock_client):
            title = await _generate_title(user_message)

        assert len(title) <= 255

    @given(user_message=user_message_strategy)
    @settings(max_examples=100)
    @pytest.mark.asyncio
    async def test_generate_title_fallback_on_bedrock_failure(
        self, user_message: str
    ) -> None:
        """_generate_title SHALL return a non-empty fallback title when
        Bedrock raises an exception, ensuring the title is never null."""
        mock_client = MagicMock()
        mock_client.invoke_model.side_effect = Exception("Bedrock unavailable")

        with patch("app.api.chat.boto3.client", return_value=mock_client):
            title = await _generate_title(user_message)

        assert title is not None
        assert isinstance(title, str)
        assert len(title) > 0
        assert title == "New conversation"

    @given(user_message=user_message_strategy)
    @settings(max_examples=100)
    @pytest.mark.asyncio
    async def test_generate_title_fallback_on_empty_bedrock_response(
        self, user_message: str
    ) -> None:
        """_generate_title SHALL return a non-empty fallback when Bedrock
        returns empty content blocks."""
        mock_body = MagicMock()
        mock_body.read.return_value = json.dumps({
            "content": []
        }).encode()

        mock_response = {"body": mock_body}
        mock_client = MagicMock()
        mock_client.invoke_model.return_value = mock_response

        with patch("app.api.chat.boto3.client", return_value=mock_client):
            title = await _generate_title(user_message)

        assert title is not None
        assert isinstance(title, str)
        assert len(title) > 0
        assert title == "New conversation"
